const {entrada:e,config:c}=$input.first().json;
const workflowNames={'PF-00':'Entrada de eventos','PF-01':'Confirmación de apartado','PF-02':'Recibo de abono','PF-03':'Abonos a distancia','PF-04':'Aviso de venta grande','PF-05':'Cierre diario','PF-06':'Recordatorios y vencimientos','PF-07':'Informe mensual','PF-08':'Avisos de error','PF-09':'Migración'};
const prefix=String(e.workflow?.name||'').match(/^PF-\d{2}/)?.[0];
const flujo=workflowNames[prefix] ? prefix+' · '+workflowNames[prefix] : 'Flujo no identificado';
// Solo nombres de pasos conocidos; nunca interpolar el mensaje/stack/URL del error.
const pasos=["Abono registrado", "Agrupar y revisar", "Analizar archivos", "Bloquear apartado", "Cada noche", "Calcular cierre", "Calcular informe", "Clasificar apartados", "Comprobar bloqueo", "Comprobar correo nuevo", "Comprobar reserva", "Confirmar abono", "Confirmar aviso de revisión", "Confirmar envío", "Confirmar operación", "Consultar abonos", "Consultar apartados", "Consultar apartados activos", "Consultar carga", "Consultar detalle", "Consultar saldo", "Consultar vales", "Consultar ventas", "Crear en tienda", "Decidir pago", "Distribuir eventos", "Ejecutar PF-01", "Ejecutar PF-02", "Ejecutar PF-04", "Ejecutar PF-06", "Ejecutar comprobación", "Enviar aviso", "Enviar informe", "Extraer pago", "Fallo controlado de prueba", "Fijar período", "Filtrar vales recientes", "Guardar revisión", "Hay liquidados", "Interpretar vencimiento", "Leer apartado del vale", "Leer configuración", "Marcar revisión", "Pago inequívoco", "Preparar aviso", "Preparar avisos de vencimiento", "Preparar consultas de detalle", "Preparar contexto", "Preparar extracción", "Preparar operaciones", "Preparar petición IA", "Preparar recordatorio", "Preparar revisión", "Primer día del mes", "Procesar cada correo del lote", "Procesar un correo", "Programar revisión diaria", "Recibir apartado de PF-00", "Recibir correos", "Recibir error", "Recibir eventos", "Recibir migración", "Recibir vencimiento de PF-00", "Recibir venta de PF-00", "Recorrer operaciones", "Redactar informe", "Redactar resultado", "Registrar abono", "Releer apartado", "Reservar correo", "Reservar operación", "Saldo permite abono", "Validar apartado", "Validar evento y destino", "Validar extracción", "Validar resultado", "Validar saldo reciente", "Validar venta y umbral", "Vencer apartado", "¿Carga autorizada?", "¿Es calendario?", "¿Es recordatorio?", "¿Reservada?"];
const rawStep=e.execution?.lastNodeExecuted||e.trigger?.error?.node?.name;
const paso=pasos.includes(rawStep)?rawStep:'no disponible';
const safeId=x=>/^[a-zA-Z0-9_-]{1,80}$/.test(String(x??''))?String(x):null;
const ejecucion=safeId(e.execution?.id), flujoId=safeId(e.workflow?.id)||'desconocido';
const kind=e.execution?.error?.name||e.trigger?.error?.name;
const autenticacion=/(?:HTTP\s*401|status\s*code\s*401)\b/i.test(String(e.execution?.error?.message||''));
const resumen=autenticacion?'Fallo de autenticacion en la API':({'NodeApiError':'No se pudo completar una llamada a un servicio.','NodeOperationError':'Un paso no pudo completar su operación.','WorkflowActivationError':'No se pudo iniciar el disparador.'})[kind]||'Fallo técnico; revisar la ejecución en n8n.';
if(!c.CORREO_MARISA||!c.CORREO_REMITENTE) throw new Error('Falta configuración de notificaciones');
const ventana=Math.floor(Date.now()/300000);
const clave=ejecucion?`error:${flujoId}:${ejecucion}`:`error:${flujoId}:${paso}:${ventana}`;
return [{json:{clave,tipo:'incidencia',documento:{flujo,paso,ejecucion,resumen,destinatario:c.CORREO_MARISA,remitente:c.CORREO_REMITENTE,asunto:`Paso Firme · Error en ${flujo}`,texto:`Flujo: ${flujo}\nPaso: ${paso}\nError: ${resumen}\nEjecución: ${ejecucion||'no disponible'}\nConsulta la instancia local de n8n para revisar el detalle.`}}}];
